let db;try{db=JSON.parse(localStorage.getItem('incremint-studio-v1'))||{bookings:[],leads:[],contacts:[],network:[],activity:[]}}catch{db={bookings:[],leads:[],contacts:[],network:[],activity:[]}}
let sidebarCollapsed=localStorage.getItem('incremint-sidebar-collapsed')==='true';
function toggleSidebar(){if(matchMedia('(max-width:600px)').matches){document.querySelector('.sidebar').classList.toggle('open');return}sidebarCollapsed=!sidebarCollapsed;localStorage.setItem('incremint-sidebar-collapsed',String(sidebarCollapsed));document.querySelector('#app').classList.toggle('sidebar-collapsed',sidebarCollapsed);document.querySelectorAll('[data-sidebar-toggle]').forEach(b=>b.setAttribute('aria-expanded',String(!sidebarCollapsed)))}
let current=location.hash.slice(1)||'dashboard', filter='All', query='', period='This month', productFilter='All products', chat=[];
const save=()=>{if(globalThis.sigmaSaveWorkspace?.())return;localStorage.setItem('incremint-studio-v1',JSON.stringify(db))};
const nav=[['dashboard','grid','Overview'],['sell','gift','Refer & earn'],['marketing','spark','Marketing kit'],['assistant','spark','AI assistant'],['bookings','shield','My bookings'],['statement','wallet','Payout statement'],['renewals','renew','Renewals'],['rates','percent','Rate card'],['leads','leads','My leads'],['network','users','My network'],['prospects','target','My prospects'],['contacts','contact','My contacts'],['help','help','Help & support'],['quotes','file','Health Quote'],['nivaquote','file','Niva Quote'],['savedquotes','file','Saved Quotes'],['settings','contact','Workspace settings'],['integrations','lock','Service connections']];
