function toast(t){document.querySelector('#toast').textContent=t;document.querySelector('#toast').classList.add('show');clearTimeout(window.to);window.to=setTimeout(()=>document.querySelector('#toast').classList.remove('show'),3000)}
function go(id){current=id;filter='All';query='';productFilter='All products';location.hash=id;render();window.scrollTo(0,0)}
function metric(label,value,icon,foot,change){return `<div class="metric"><div class="metriclabel">${label}${I(icon)}</div><div class="metricvalue">${value}</div><div class="metricfooter">${change?`<span class="change">${change}</span>`:''}${foot}</div></div>`}
function heading(eyebrow,title,desc,actions=''){return `<div class="pageheading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><div class="subtle">${desc}</div></div><div class="actions">${actions}</div></div>`}
const btn=(t,action,icon,primary=false)=>`<button ${primary?'class="primary"':''} onclick="${esc(action)}">${icon?I(icon):''}${t}</button>`;
const initials=n=>n.split(' ').map(x=>x[0]).slice(0,2).join('');
const total=()=>db.bookings.reduce((s,b)=>s+Number(b.premium),0);
function bookingRows(rows){return rows.map(b=>`<tr><td><div class="person"><div class="initial">${initials(b.name)}</div><div><strong>${esc(b.name)}</strong><small>${b.id}</small></div></div></td><td>${esc(b.product)}</td><td>${rupee(b.premium)}</td><td><span class="badge ${b.status==='Issued'?'dark':''}">${esc(b.status)}</span></td><td><button class="quiet" aria-label="View ${esc(b.name)} booking" onclick="viewBooking('${b.id}')">${I('dots')}</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">No bookings match your filters.</td></tr>'}
function recentTable(rows=db.bookings.slice(0,4)){return `<div class="tablewrap"><table><thead><tr><th>Customer</th><th>Product</th><th>Premium</th><th>Status</th><th></th></tr></thead><tbody>${bookingRows(rows)}</tbody></table></div>`}
function chart(){let factors={'This month':1,'Last month':.78,'This FY':5.4,'Last FY':4.1};let f=factors[period]||1;return `<div class="chartlegend"><span class="legenditem"><i class="legendline"></i>Current period</span><span class="legenditem"><i class="legendline dashed"></i>Previous period</span></div><div class="chart"><svg viewBox="0 0 650 230" preserveAspectRatio="none" role="img" aria-label="Premium trend from June to November"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#087fff" stop-opacity=".24"/><stop offset="1" stop-color="#087fff" stop-opacity="0"/></linearGradient></defs>${[40,85,130,175].map((y,i)=>`<path d="M48 ${y}H630" stroke="#efefef" stroke-dasharray="3 4"/><text x="2" y="${y+4}">₹${Math.round((3-i)*f)}L</text>`).join('')}<path d="M48 158C95 158 112 137 160 145S220 173 276 133 326 138 390 100 447 133 508 84 567 102 630 43V195H48Z" fill="url(#area)"/><path d="M48 175C105 175 125 153 160 161S225 145 276 150 338 111 390 135 455 99 508 119 570 73 630 94" stroke="#a9bddb" fill="none" stroke-width="2" stroke-dasharray="4 5"/><path d="M48 158C95 158 112 137 160 145S220 173 276 133 326 138 390 100 447 133 508 84 567 102 630 43" stroke="#087fff" fill="none" stroke-width="2.7"/><circle cx="630" cy="43" r="4" fill="#fff" stroke="#087fff" stroke-width="2"/>${['Jun','Jul','Aug','Sep','Oct','Nov'].map((m,i)=>`<text x="${48+i*115}" y="222">${m}</text>`).join('')}</svg></div>`}
function overview(){let issued=db.bookings.filter(b=>b.status==='Issued').length,openLeads=db.leads.filter(l=>!['Issued','Lost'].includes(l.status)).length,renewals=db.bookings.filter(b=>!b.renewed).length,goal=Math.min(100,Math.round(total()/500000*100));return heading('PARTNER COMMAND CENTER','Business overview','Everything you need to move your business forward.',`${btn('Export report',"download('bookings')",'download')}${btn('New booking',"openForm('booking')",'plus',true)}`)+`
<section class="welcome-banner"><div class="welcome-copy"><span class="welcome-kicker">${I('spark')} A NEW DAY. NEW POSSIBILITIES.</span><h2>Your next chapter<br>looks <em>promising.</em></h2><p>Welcome back, Deepak. Build stronger relationships,<br class="desktop-break"> protect more futures, and make every opportunity count.</p><div class="welcome-actions">${btn('Explore opportunities',"go('leads')",'target',true)}<span>${I('shield')} Your Insurance Business, Simplified.</span></div></div><div class="welcome-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="art-shield">${I('shield')}<span class="art-check">${I('check')}</span></div><div class="floating-label float-top">${I('trend')} Built for growth</div><div class="floating-label float-bottom">${I('heart')} People first. Always.</div><span class="art-dot dot-one"></span><span class="art-dot dot-two"></span></div></section>
<div class="overview-period"><div><span class="live-indicator"></span><strong>Your performance</strong><span class="subtle">${new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'long',year:'numeric'}).format(new Date())}</span><span class="demo">SAMPLE WORKSPACE</span></div><select aria-label="Reporting period" onchange="period=this.value;render()">${['This month','Last month','This FY','Last FY'].map(p=>`<option ${p===period?'selected':''}>${p}</option>`).join('')}</select></div>
<div class="metrics">${metric('Business volume',rupee(Math.round(total()*({'This month':1,'Last month':.78,'This FY':5.4,'Last FY':4.1}[period]||1))),'trend',`${db.bookings.length} policies this month`,'+18.6%')}${metric('Lead points',Math.round(total()*.1).toLocaleString('en-IN')+' pts','target','On your bookings this period','+12.4%')}${metric('Points received','14,850 pts','wallet','Credited to your account','+8.2%')}${metric('Points pending','6,695 pts','clock','Next payout · 5 December','Upcoming')}</div>
<div class="performance-grid"><section class="card performance-card"><div class="cardhead"><div><span class="card-eyebrow">THE BIG PICTURE</span><h2>Business performance</h2><p>A little progress every day adds up.</p></div><span class="chart-period">6-month trend</span></div><div class="chart-summary"><strong>${rupee(total())}</strong><span class="growth-chip">${I('trend')} 18.6%</span><span class="subtle">vs. previous period · sample trend</span></div>${chart()}</section><section class="card goal-card"><div class="cardhead"><div><span class="card-eyebrow">KEEP THE MOMENTUM</span><h2>Your monthly milestone</h2></div>${I('target')}</div><div class="goal-ring" style="--progress:${goal*3.6}deg"><div><span>MONTHLY GOAL</span><strong>${goal}<small>%</small></strong><span>of ₹5,00,000</span></div></div><div class="goal-numbers"><div><span>Achieved</span><strong>${rupee(total())}</strong></div><div><span>To go</span><strong>${rupee(Math.max(0,500000-total()))}</strong></div></div><div class="goal-note">${I('spark')} Your next booking brings you closer.</div></section></div>
<div class="sectiontitle"><div><span class="card-eyebrow">TURN POSSIBILITIES INTO POLICIES</span><h2>What would you like to insure?</h2></div><button class="linkbutton" onclick="go('sell')">Explore all products ${I('grid')}</button></div><div class="product-grid">${products.map(([p,i])=>`<button class="product" onclick="${p==='All products'?"go('sell')":`openForm('lead','${p}')`}"><span class="product-symbol">${I(i)}</span><strong>${p}</strong><small>${{Health:'Care that goes further',Life:'For what matters most',Motor:'Confidence in every mile',Term:'A secure tomorrow',Travel:'Go beyond the everyday','All products':'Find the right protection'}[p]}</small></button>`).join('')}</div>
<div class="insights-strip"><div class="insight-icon">${I('spark')}</div><div><span class="insight-kicker">SIGMA0NINE COPILOT</span><h3>Your next best move, a little clearer.</h3><p>${openLeads} open leads and ${renewals} renewal follow-ups. Get a focused plan for your day.</p></div>${btn('Ask your assistant',"go('assistant')",'spark',true)}</div>
<div class="bottomgrid"><section class="card tablecard"><div class="cardhead"><div><span class="card-eyebrow">MAKING THINGS HAPPEN</span><h2>Recent bookings <span class="count-bubble">${db.bookings.length}</span></h2><p>${issued} issued policies. More futures protected.</p></div><button class="linkbutton" onclick="go('bookings')">View all bookings</button></div>${recentTable()}</section><section class="card renewals-card"><div class="cardhead"><div><span class="card-eyebrow">RELATIONSHIPS THAT LAST</span><h2>Upcoming renewals</h2><p>A timely hello makes a difference.</p></div><span class="calendar-icon">${I('calendar')}</span></div>${db.bookings.filter(b=>!b.renewed).slice(0,3).map(b=>`<div class="renewal-item"><div class="renewal-icon">${I(products.find(p=>p[0]===b.product)?.[1]||'shield')}</div><div class="renewal-text"><strong>${esc(b.name)}</strong><small>${b.product} · ${b.insurer}</small></div><div class="renewal-date">${new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short'}).format(new Date(b.renewal+'T00:00:00'))}<small>Follow-up due</small></div></div>`).join('')||'<div class="empty">All renewals are up to date.</div>'}<button class="renewal-all" onclick="go('renewals')">Manage renewals ${I('renew')}</button></section></div>`}

function tabs(items){return `<div class="tabs">${items.map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';render()">${t}</button>`).join('')}</div>`}
function search(placeholder='Search customers, policies…'){return `<div class="searchbox">${I('search')}<input aria-label="${placeholder}" placeholder="${placeholder}" value="${esc(query)}" oninput="query=this.value;updateResults()"></div>`}
function bookings(){return heading('BUSINESS','Every policy. One place.','Manage your bookings and keep every customer in focus.',btn('Export CSV',"download('bookings')",'download')+btn('Add booking',"openForm('booking')",'plus',true))+`<div class="metrics">${metric('Total premium',rupee(total()),'trend','Across all bookings')}${metric('Policies issued',db.bookings.filter(b=>b.status==='Issued').length,'shield','Successfully issued')}${metric('In progress',db.bookings.filter(b=>b.status==='Processing').length,'clock','We’re working on these')}${metric('Estimated points',Math.round(total()*.1).toLocaleString('en-IN'),'wallet','Illustrative at 10%')}</div><div class="toolbar">${search()}<select aria-label="Filter product" onchange="productFilter=this.value;updateResults()">${['All products','Health','Life','Motor','Term','Travel'].map(p=>`<option>${p}</option>`).join('')}</select><input type="month" aria-label="Filter booking month" onchange="window.bookingMonth=this.value;updateResults()"></div><section class="card" id="results">${recentTable(filteredBookings())}</section>`}
function filteredBookings(){return db.bookings.filter(b=>(b.name+' '+b.id+' '+b.insurer).toLowerCase().includes(query.toLowerCase())&&(productFilter==='All products'||b.product===productFilter)&&(!window.bookingMonth||b.date.startsWith(window.bookingMonth)))}
function leads(prospect=false){return heading('CONNECTIONS',prospect?'Tomorrow’s partners. Today’s potential.':'From first hello to a new policy.',prospect?'A focused view of your agent prospects.':'A clear pipeline. A more personal way to grow.',btn('Export CSV',"download('leads')",'download')+btn(prospect?'Add prospect':'Add lead',`openForm('${prospect?'prospect':'lead'}')`,'plus',true))+`<div class="toolbar">${search('Search leads by name or product…')}${btn('List view',"filter=filter==='List'?'All':'List';render()",'grid')}</div><div id="results">${leadResults(prospect)}</div>`}
function leadResults(prospect=false){let rows=(prospect?db.contacts.filter(c=>c.type==='Prospect').map(c=>({...c,status:'New',product:'Agent prospect',premium:0})):db.leads).filter(l=>(l.name+' '+l.product).toLowerCase().includes(query.toLowerCase()));if(filter==='List')return `<section class="card"><table><thead><tr><th>Name</th><th>Product</th><th>Value</th><th>Stage</th></tr></thead><tbody>${rows.map(l=>`<tr><td>${esc(l.name)}</td><td>${esc(l.product)}</td><td>${rupee(l.premium)}</td><td>${esc(l.status)}</td></tr>`).join('')}</tbody></table></section>`;return `<div class="kanban">${['New','Quote given','Booked','Issued'].map(s=>`<div class="column"><h3>${s}<span class="subtle">${rows.filter(l=>l.status===s).length}</span></h3>${rows.filter(l=>l.status===s).map(l=>`<article class="leadcard"><span class="badge">${esc(l.product)}</span><h4>${esc(l.name)}</h4><p>${l.phone?esc(l.phone):'No phone added'}<br>Potential premium: ${rupee(l.premium)}</p>${!prospect?`<select aria-label="Stage for ${esc(l.name)}" onchange="moveLead('${l.id}',this.value)">${['New','Quote given','Booked','Issued','Lost'].map(v=>`<option ${v===s?'selected':''}>${v}</option>`).join('')}</select>`:btn('View contact',`contactDetail('${l.id}')`,'contact')}</article>`).join('')||'<div class="subtle" style="padding:15px 0">Room for your next opportunity.</div>'}</div>`).join('')}</div>`}
function moveLead(id,status){db.leads.find(l=>l.id===id).status=status;save();render();toast('Lead moved to '+status)}
function statement(){return heading('YOUR EARNINGS','Good work. Well rewarded.','A clear view of your points and upcoming payouts.',btn('Download statement',"download('statement')",'download'))+`<div class="notice">Sample payout statement. Amounts are illustrative and are not connected to a payment provider.</div><div class="metrics">${metric('Total earned','21,545 pts','wallet','This financial year')}${metric('Total cleared','14,850 pts','check','Received in your account')}${metric('Next cycle due','6,695 pts','calendar','5 December 2026')}${metric('Overdue','0 pts','clock','You’re all caught up')}</div><section class="card tablecard"><div class="cardhead"><div><h2>Upcoming payouts</h2><p>Your next bit of progress</p></div><span class="badge">5 Dec 2026</span></div><table><thead><tr><th>Customer</th><th>Policy</th><th>Points</th><th>Status</th></tr></thead><tbody>${db.bookings.slice(0,3).map(b=>`<tr><td>${esc(b.name)}</td><td>${b.id}</td><td>${Math.round(b.premium*.1).toLocaleString('en-IN')} pts</td><td><span class="badge">Scheduled</span></td></tr>`).join('')}</tbody></table></section><section class="card" style="margin-top:22px"><div class="cardhead"><h2>Recently cleared</h2></div><div class="activity">${I('check')}<div><strong>November payout · 14,850 pts</strong><small>Credited on 20 November 2026 · Sample transaction</small></div></div></section>`}
function renewals(){return heading('STAY ONE STEP AHEAD','Keep a good thing going.','Timely renewals. Lasting relationships.',btn('Export renewals',"download('renewals')",'download'))+`<div class="metrics">${metric('Renewal premium',rupee(total()),'renew',`${db.bookings.length} policies in your book`)}${metric('Due this month',db.bookings.filter(b=>b.renewal.startsWith('2026-11')).length,'calendar','November 2026')}${metric('Renewed',db.bookings.filter(b=>b.renewed).length,'check','Relationships continued')}${metric('Needs follow-up',db.bookings.filter(b=>!b.renewed).length,'phone','A conversation makes a difference')}</div>${tabs(['All','This month','Next month','Renewed'])}<div class="toolbar">${search('Search renewals…')}</div><div id="results">${renewalResults()}</div>`}
function renewalResults(){let rows=db.bookings.filter(b=>b.name.toLowerCase().includes(query.toLowerCase())&&(filter==='All'||filter==='This month'&&b.renewal.startsWith('2026-11')||filter==='Next month'&&b.renewal.startsWith('2026-12')||filter==='Renewed'&&b.renewed));return `<section class="card"><div class="tablewrap"><table><thead><tr><th>Customer</th><th>Product / insurer</th><th>Expiry date</th><th>Premium</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${esc(b.name)}</td><td>${b.product}<div class="subtle">${b.insurer}</div></td><td>${b.renewal}</td><td>${rupee(b.premium)}</td><td><span class="badge">${b.renewed?'Renewed':'Follow-up'}</span></td><td>${btn(b.renewed?'View policy':'Renew policy',b.renewed?`viewBooking('${b.id}')`:`renewPolicy('${b.id}')`,'renew')}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No renewals match this view.</td></tr>'}</tbody></table></div></section>`}
function renewPolicy(id){db.bookings.find(b=>b.id===id).renewed=true;save();render();toast('Policy marked as renewed')}
const rates=[{name:'Care Health',product:'Health',plans:[['Care Supreme + NCB Super',27,20,12.5],['Ultimate Care',24,20,10.59],['Care Supreme',20,17.5,10.59]]},{name:'Tata AIG',product:'Health',plans:[['Medicare Lite',25,10,10],['Medicare Premier',25,10,10],['Medicare Select',22.5,10,10]]},{name:'HDFC Life',product:'Life',plans:[['Sanchay Plus',22,15,8],['Click 2 Protect',20,12,7]]},{name:'ICICI Lombard',product:'Motor',plans:[['Comprehensive car',18,12,10],['Two wheeler package',15,10,8]]},{name:'Tata AIG',product:'Travel',plans:[['Travel Guard',20,10,10]]},{name:'HDFC Life',product:'Term',plans:[['Click 2 Protect Super',25,15,10]]},{name:'Bajaj Allianz',product:'SME',plans:[['Business Shield',18,10,8]]}];
function ratePage(){return heading('PAYOUT INTELLIGENCE','A better view of your possibilities.','Compare sample payout rates, find the right plan, and move confidently.','<span class="badge">ILLUSTRATIVE RATES</span>')+tabs(['All','Health','Life','Motor','Travel','Term','SME'])+`<div class="toolbar">${search('Search insurer or plan…')}</div><div id="results">${rateResults()}</div>`}
function rateResults(){return `<div class="ratecards">${rates.filter(r=>(filter==='All'||r.product===filter)&&(r.name+' '+r.plans.flat().join(' ')).toLowerCase().includes(query.toLowerCase())).map(r=>`<section class="card"><div class="ratehead"><div><h3>${r.name}</h3><p>${r.product} · ${r.plans.length} active plans · Pan India</p></div><span class="badge">Top payout ${Math.max(...r.plans.map(p=>p[1]))} pts</span></div><div class="tablewrap"><table><thead><tr><th>Plan name</th><th>New business</th><th>Port-in</th><th>Renewal</th><th></th></tr></thead><tbody>${r.plans.map(p=>`<tr><td>${p[0]}</td><td><strong>${p[1].toFixed(2)} pts</strong></td><td>${p[2].toFixed(2)} pts</td><td>${p[3].toFixed(2)} pts</td><td>${btn('Create quote',`openForm('lead','${r.product}')`,'plus')}</td></tr>`).join('')}</tbody></table></div></section>`).join('')||'<div class="empty">No plans match your search.</div>'}</div>`}
function contacts(){return heading('YOUR PEOPLE','Relationships worth keeping.','All your customers, leads, and partners, thoughtfully organised.',btn('Export contacts',"download('contacts')",'download')+btn('Add contact',"openForm('contact')",'plus',true))+`<div class="toolbar">${search('Search name, phone, or email…')}</div>${tabs(['All','Customer','Lead','Prospect'])}<div id="results">${contactResults()}</div>`}
function contactResults(){return `<div class="contactgrid">${db.contacts.filter(c=>(filter==='All'||c.type===filter)&&(c.name+' '+c.email+' '+c.phone).toLowerCase().includes(query.toLowerCase())).map(c=>`<article class="card pad contactcard"><div class="initial">${initials(c.name)}</div><span class="badge">${c.type}</span><h3>${esc(c.name)}</h3><p>${esc(c.email||'No email added')}<br>${esc(c.phone)}</p><div class="actions">${btn('View contact',`contactDetail('${c.id}')`,'contact')}${btn('Add lead',`openForm('lead','Health','${c.id}')`,'plus')}</div></article>`).join('')||'<div class="empty">No contacts found. Add a contact to get started.</div>'}</div>`}
function network(){return heading('BETTER TOGETHER','Good connections. Great possibilities.','Grow your network of insurance partners.',btn('Invite a partner',"invite()",'plus',true))+`<section class="hero"><div class="eyebrow" style="color:#aaa">THE PARTNER PROGRAMME</div><h2>Build your network.<br>Multiply your potential.</h2><p>Bring great people into your circle. Track your team’s business and celebrate every milestone together.</p>${btn('Copy invitation link',"copyLink()",'copy')}</section><div class="metrics">${metric('Active partners',db.network.length,'users','Your growing circle')}${metric('Team policies',db.network.reduce((s,n)=>s+n.policies,0),'shield','Across your network')}${metric('Team premium',rupee(db.network.reduce((s,n)=>s+n.premium,0)),'trend','Illustrative business volume')}${metric('Referral points','5,370 pts','gift','Sample network earnings')}</div><section class="card"><table><thead><tr><th>Partner</th><th>City</th><th>Policies</th><th>Premium</th></tr></thead><tbody>${db.network.map(n=>`<tr><td>${esc(n.name)}</td><td>${esc(n.city)}</td><td>${n.policies}</td><td>${rupee(n.premium)}</td></tr>`).join('')}</tbody></table></section>`}
function sell(){return heading('NEW POSSIBILITIES','The right cover. A fresh start.','Create a lead for any product, and we’ll keep it in your pipeline.',btn('Copy referral link',"copyLink()",'copy'))+`<section class="hero"><div class="eyebrow" style="color:#aaa">REFER & EARN</div><h2>A little introduction.<br>A lasting difference.</h2><p>Share your personalised referral link with a customer and start a new conversation about their financial wellbeing.</p>${btn('View your network',"go('network')",'users')}</section>${[['General insurance',[['Health','heart'],['Motor','car'],['Travel','plane'],['Group Health','users'],['Group PA','shield'],['Home','home']]],['Life & investments',[['Term','shield'],['Life','heart'],['Investment','trend'],['Mutual Fund','wallet']]],['Commercial & other',[['Fire & Burglary','shield'],['Jewellery Block','briefcase'],['Marine','plane'],['Workmen Compensation','users']]]].map(([title,ps])=>`<div class="sectiontitle"><h2>${title}</h2></div><div class="product-grid">${ps.map(([p,i])=>`<button class="product" onclick="openForm('lead','${p}')">${I(i)}${p}</button>`).join('')}</div>`).join('')}`}
const posters=[['Health','Your health deserves a stronger safety net.','A little care today. A more secure tomorrow.'],['Life','For the life you’re building.','Protect the people who make it worthwhile.'],['Motor','Every journey. A little more assured.','Give your car the cover it deserves.'],['Term','Big dreams need a backup plan.','Make room for peace of mind.'],['Travel','Go a little further. Worry a little less.','Explore the world with confidence.'],['General','A better tomorrow starts today.','Your trusted partner in protection.']];
function marketing(){return heading('MAKE YOUR MARK','Your expertise. Beautifully shared.','Personalise ready-to-share creatives for your customers.','<span class="badge">6 EDITABLE CREATIVES</span>')+tabs(['All','Health','Life','Motor','Term','Travel'])+`<div class="poster-grid">${posters.filter(p=>filter==='All'||p[0]===filter).map((p,i)=>`<article class="card"><div class="poster ${i%2?'inverse':''}"><small>SIGMA0NINE / ${p[0].toUpperCase()}</small>${I(products.find(x=>x[0]===p[0])?.[1]||'shield')}<h3>${p[1]}</h3><div class="subtle">${p[2]}</div></div><div class="posterbottom"><strong>${p[0]} essentials</strong>${btn('Personalise',`personalise('${p[0]}')`,'plus')}</div></article>`).join('')}</div>`}
function assistant(){return heading('YOUR BUSINESS COPILOT','A little help. Right when you need it.','Turn your workspace data into useful next steps.','<span class="badge">LOCAL ASSISTANT DEMO</span>')+`<div class="chatlayout"><div class="chatwelcome">${I('spark')}<h2>What can we move forward today?</h2><p class="subtle">Explore your pipeline, prioritise renewals, or draft a customer message.<br>This demo uses local templates and your workspace records.</p></div><div class="suggestions">${['Give me a business summary','Which renewals need attention?','Draft a renewal reminder','How can I follow up with new leads?'].map(p=>`<button onclick="ask('${p}')">${I('spark')}${p}</button>`).join('')}</div><div class="messages" id="messages">${chat.map(m=>`<div class="message ${m.role}">${esc(m.text)}</div>`).join('')}</div><form class="chatinput" onsubmit="event.preventDefault();ask(this.prompt.value);this.reset()"><input name="prompt" aria-label="Ask assistant" placeholder="Ask about your business…" required autocomplete="off"><button class="primary" type="submit">${I('spark')} Ask</button></form></div>`}
function ask(prompt){if(!prompt.trim())return;chat.push({role:'user',text:prompt});let p=prompt.toLowerCase(),answer;if(/renew|remind/.test(p)){answer=/draft|message|reminder/.test(p)?`Hi ${db.bookings[1]?.name||'there'}, a quick reminder that your ${db.bookings[1]?.product||'insurance'} policy is due for renewal on ${db.bookings[1]?.renewal||'the upcoming renewal date'}. I’d be happy to help you review your cover and renew it on time. Would you like me to prepare the details?\n\nPlease verify the policy details before sharing this draft.`:`${db.bookings.filter(b=>!b.renewed).length} policies need a renewal follow-up.\n\n${db.bookings.filter(b=>!b.renewed).slice(0,4).map(b=>`${b.name} · ${b.product} · ${b.renewal}\nPremium: ${rupee(b.premium)}`).join('\n\n')}\n\nStart with the earliest expiry and confirm the customer’s current requirements.`}else if(/lead|follow/.test(p)){answer=`You have ${db.leads.filter(l=>l.status==='New').length} new leads and ${db.leads.filter(l=>l.status==='Quote given').length} quotes awaiting a decision.\n\nStart with ${db.leads.find(l=>l.status==='New')?.name||'your newest lead'}. Here’s a draft:\n\n“Hi, thanks for your interest in insurance cover. Would you have a few minutes to discuss your requirements and budget? I can help you compare suitable options.”\n\nConfirm needs, prepare a quote, and update the lead stage after the conversation.`}else if(/summary|business|performance|premium/.test(p)){answer=`Here’s your workspace at a glance:\n\nBusiness volume: ${rupee(total())}\nBookings: ${db.bookings.length}\nIssued policies: ${db.bookings.filter(b=>b.status==='Issued').length}\nOpen leads: ${db.leads.filter(l=>!['Issued','Lost'].includes(l.status)).length}\nContacts: ${db.contacts.length}\n\nYour next move: follow up with fresh leads and review upcoming renewals. These figures come from the sample data and records saved in this browser.`}else{answer='I can help with your business summary, lead follow-ups, renewal priorities, and customer message drafts. Try “Give me a business summary” or “Draft a renewal reminder”.\n\nThis is a local assistant demo. A live AI model has not been connected.'}chat.push({role:'assistant',text:answer});render();document.querySelector('#messages')?.lastElementChild?.scrollIntoView({behavior:'smooth',block:'nearest'})}
function help(){const qs=[['How do I add a booking?','Choose Add booking, enter the customer, insurer, premium and policy dates, then save. Your new booking appears in My bookings and updates the overview metrics. Records are stored in this browser.'],['How do I manage my lead pipeline?','Open My leads to add leads and change their stage using the menu on each card. Choose List view for a compact overview.'],['How do payouts work?','The statement shows illustrative earned, cleared and upcoming points. Live payout tracking requires a connected backend and payment records.'],['How do I personalise a marketing creative?','Choose a creative in Marketing kit, add your name and phone number, then download the SVG. You can open it in a browser or share the exported file.'],['How do I export my records?','Use Export CSV on bookings, contacts, leads or renewals. The downloaded file can be opened in Excel or Google Sheets.'],['Is the assistant connected to a live AI model?','The current assistant provides local template responses based on your records. Connect a server-side AI endpoint to enable open-ended model responses.'],['Where is my data saved?','This demo uses localStorage in your current browser. It does not sync across devices. Production use needs authentication, a database, access controls and backups.']];return heading('A LITTLE GUIDANCE','Good questions. Clear answers.','Everything you need to get the most from your workspace.')+`<div class="toolbar">${search('Search help articles…')}</div><section class="card" id="results">${qs.filter(q=>q.join(' ').toLowerCase().includes(query.toLowerCase())).map(([q,a])=>`<details class="help-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`}
function quotes(){return heading('START A CONVERSATION','A clearer picture of the possibilities.','Calculate an illustrative premium and create a lead.')+`<div class="split"><section class="card pad"><h2>Quick premium estimate</h2><p class="paneltext">A planning tool for a first conversation. Final premiums depend on underwriting and the insurer’s quote.</p><form id="estimate" onsubmit="event.preventDefault();estimate(this)"><div class="formgrid"><label class="field">Product<select name="product"><option>Health</option><option>Term</option><option>Motor</option><option>Travel</option></select></label><label class="field">Customer age<input name="age" type="number" min="18" max="85" value="30" required></label><label class="field full">Coverage amount (₹)<input name="cover" type="number" min="100000" max="100000000" value="1000000" required></label><div class="field full"><button class="primary" type="submit">Calculate estimate</button></div></div></form><div id="quoteResult"></div></section><section class="ai-card"><div class="ai-label">${I('shield')} A THOUGHTFUL FIRST STEP</div><h2>The right cover starts<br>with the right conversation.</h2><p>Understand your customer’s needs, compare appropriate plans, and explain the exclusions clearly.</p><button onclick="go('rates')">Compare sample rate cards</button></section></div>`}
function estimate(form){let f=new FormData(form),age=+f.get('age'),cover=+f.get('cover'),p=f.get('product'),premium=Math.round(cover*({Health:.012,Term:.0018,Motor:.028,Travel:.003}[p])*(1+Math.max(0,age-30)*.035));document.querySelector('#quoteResult').innerHTML=`<div class="quote-result"><div class="eyebrow">ILLUSTRATIVE ANNUAL PREMIUM</div><p><strong>${rupee(premium)}</strong> / year</p><p class="subtle">Excludes taxes. This is a sample calculation, not an insurer quote.</p>${btn('Create lead',`openForm('lead','${p}')`,'plus',true)}</div>`}
function updateResults(){let el=document.querySelector('#results');if(!el)return;if(current==='bookings')el.innerHTML=recentTable(filteredBookings());if(current==='leads'||current==='prospects')el.innerHTML=leadResults(current==='prospects');if(current==='contacts')el.innerHTML=contactResults();if(current==='rates')el.innerHTML=rateResults();if(current==='renewals')el.innerHTML=renewalResults();if(current==='help'){let pos=document.activeElement.selectionStart;let val=query;render();let inp=document.querySelector('.searchbox input');inp.focus();inp.setSelectionRange(pos,pos)}}
function render(){document.querySelector('#app').classList.toggle('sidebar-collapsed',sidebarCollapsed);let title=nav.find(n=>n[0]===current)?.[2]||'Overview';let pages={dashboard:overview,bookings,leads,prospects:()=>leads(true),statement,renewals,rates:ratePage,contacts,network,sell,marketing,assistant,help,quotes,leadform:leadFormPage,nivaquote:nivaQuotePage,savedquotes:savedQuotesPage,settings:settingsPage,integrations:integrationsPage};if(!pages[current])current='dashboard';document.title=`${title} — Sigma0Nine`;document.querySelector('#app').innerHTML=`<aside class="sidebar"><button class="quiet sidebar-close" aria-label="Close navigation" onclick="toggleSidebar()">${I('close')}</button><a class="brand" href="#dashboard" aria-label="Sigma0Nine home"><img src="sigma0nine-logo.png" alt="Sigma0Nine — Your Insurance Business, Simplified."></a><div class="workspace"><div class="avatar">IP</div><div><strong>Partner workspace</strong><small>Your growth headquarters</small></div>${I('down')}</div><div class="navlabel">WORKSPACE</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,icon,label],i)=>`${i===8?'<div class="navlabel navsep">CONNECTIONS</div>':i===12?'<div class="navlabel navsep">RESOURCES</div>':''}<button class="${current===id?'active':''}" onclick="go('${id}')" title="${label}">${I(icon)}${label}${id==='assistant'?'<span class="pill">AI</span>':''}</button>`).join('')}</nav><div class="sidebarbottom"><div class="avatar">DS</div><div><strong>Deepak Sharma</strong><small>Partner account</small></div><button class="quiet" aria-label="Account settings" onclick="settings()">${I('dots')}</button></div></aside><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="quiet mobilemenu" data-sidebar-toggle onclick="toggleSidebar()" aria-expanded="${!sidebarCollapsed}" aria-label="Toggle navigation">${I('menu')}</button><span>Workspace</span><span>/</span><strong>${title}</strong></div><div class="topright"><button class="global-search" onclick="globalSearch()">${I('search')} Search anything <span class="key">⌘ K</span></button><div class="divider"></div><button class="quiet notification" aria-label="Notifications" onclick="notifications()">${I('bell')}</button><button class="avatar" aria-label="Account settings" onclick="settings()">DS</button></div></header><main class="content">${pages[current]()}<footer class="footer"><span>© 2026 Sigma0Nine. Your Insurance Business, Simplified.</span><span>${I('lock')} Your workspace. Your possibilities.</span></footer></main></div>`}
function modal(title,body){document.querySelector('#overlay').innerHTML=`<div class="modalbackdrop" onclick="if(event.target===this)closeModal()"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${title}</h2><button class="quiet" aria-label="Close dialog" onclick="closeModal()">${I('close')}</button></div><div class="modalbody">${body}</div></section></div>`;document.querySelector('.modal input,.modal button')?.focus()}
function closeModal(){document.querySelector('#overlay').innerHTML=''}
function openForm(type,product='Health',cid=''){let c=db.contacts.find(c=>c.id===cid)||{};const field=(label,name,kind='text',value='',required=true)=>`<label class="field">${label}<input name="${name}" type="${kind}" value="${esc(value)}" ${required?'required':''} ${kind==='number'?'min="1" max="100000000"':kind==='tel'?'pattern="[0-9+ ()-]{8,16}"':''}></label>`;const select=(label,name,opts)=>`<label class="field">${label}<select name="${name}">${opts.map(v=>`<option ${v===product?'selected':''}>${v}</option>`).join('')}</select></label>`;let fields=field('Full name','name','text',c.name||'');if(type==='contact'||type==='prospect'){fields+=field('Phone number','phone','tel',c.phone||'')+field('Email address','email','email',c.email||'',false)+select('Contact type','type',type==='prospect'?['Prospect']:['Customer','Lead','Prospect'])}else{fields+=select('Product','product',[...new Set([product,'Health','Life','Motor','Term','Travel','Group Health','Home','Mutual Fund','SME'])])+field('Premium (₹)','premium','number','')+field('Phone number','phone','tel',c.phone||'',type==='lead');if(type==='booking')fields+=field('Insurer','insurer')+field('Booking date','date','date','2026-11-23')+field('Renewal date','renewal','date','2027-11-23')+select('Policy status','status',['Processing','Issued'])}
modal(type==='booking'?'Add a booking':type==='lead'?'Create a new lead':type==='prospect'?'Add a prospect':'Add a contact',`<form onsubmit="event.preventDefault();submitForm(this,'${type}')"><div class="formgrid">${fields}</div><p class="subtle">Saved to this browser’s workspace.</p><div class="modalfoot"><button type="button" onclick="closeModal()">Cancel</button><button class="primary" type="submit">${I('check')} Save ${type}</button></div></form>`)}
function submitForm(form,type){let v=Object.fromEntries(new FormData(form));v.name=v.name.trim();if(!v.name){toast('Please enter a name');return}v.id=(type==='booking'?'INC-':type==='lead'?'L':'C')+Date.now().toString().slice(-7);if(type==='booking'&&v.renewal<=v.date){toast('Renewal date must be after booking date');return}if(v.premium)v.premium=Number(v.premium);if(type==='booking')db.bookings.unshift(v);else if(type==='lead'){v.status='New';db.leads.unshift(v)}else db.contacts.unshift(v);db.activity.unshift({text:`${type} added for ${v.name}`,date:new Date().toLocaleString('en-IN')});save();closeModal();render();toast('Saved successfully')}
function viewBooking(id){let b=db.bookings.find(b=>b.id===id);modal('Policy details',`<span class="badge">${b.id}</span><h2>${esc(b.name)}</h2><p>${b.product} insurance · ${esc(b.insurer)}<br>Premium: ${rupee(b.premium)}<br>Booked: ${b.date}<br>Renewal: ${b.renewal}<br>Status: ${b.status}${b.renewed?' · Renewed':''}</p><div class="modalfoot">${btn('Download record',`downloadRecord('${id}')`,'download')}${btn(b.status==='Issued'?'Close':'Mark issued',b.status==='Issued'?'closeModal()':`issue('${id}')`,'check',true)}</div>`)}
function issue(id){db.bookings.find(b=>b.id===id).status='Issued';save();closeModal();render();toast('Policy marked as issued')}
function contactDetail(id){let c=db.contacts.find(c=>c.id===id);modal('Contact details',`<h2>${esc(c.name)}</h2><span class="badge">${c.type}</span><p>${esc(c.email||'No email added')}<br>${esc(c.phone)}</p><div class="modalfoot">${btn('Edit contact',`editContact('${id}')`,'contact')}${btn('Create lead',`openForm('lead','Health','${id}')`,'plus',true)}</div>`)}
function editContact(id){let c=db.contacts.find(c=>c.id===id);modal('Edit contact',`<form onsubmit="event.preventDefault();let c=db.contacts.find(c=>c.id==='${id}');Object.assign(c,Object.fromEntries(new FormData(this)));save();closeModal();render();toast('Contact updated')"><div class="formgrid">${['name','phone','email'].map(k=>`<label class="field ${k==='name'?'full':''}">${k}<input name="${k}" type="${k==='email'?'email':k==='phone'?'tel':'text'}" value="${esc(c[k])}" ${k==='email'?'':'required'}></label>`).join('')}</div><div class="modalfoot"><button class="primary">Save changes</button></div></form>`)}
function fileDownload(name,data,type='text/csv;charset=utf-8'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csv(rows){if(!rows.length){toast('No records to export');return null}let keys=Object.keys(rows[0]);return '\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]??''))].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""').replace(/^[=+@-]/,"' $&")+'"').join(',')).join('\r\n')}
function download(type){let rows=type==='bookings'?filteredBookings():type==='contacts'?db.contacts:type==='leads'?db.leads:type==='renewals'?db.bookings.map(({name,product,insurer,premium,renewal,renewed})=>({name,product,insurer,premium,renewal,status:renewed?'Renewed':'Follow-up'})):db.bookings.slice(0,3).map(b=>({customer:b.name,policy:b.id,points:Math.round(b.premium*.1),status:'Scheduled',due:'2026-12-05'}));let data=csv(rows);if(data){fileDownload(`incremint-${type}.csv`,data);toast('Your CSV export is ready')}}
function downloadRecord(id){let data=csv([db.bookings.find(b=>b.id===id)]);fileDownload(`${id}.csv`,data);toast('Policy record downloaded')}
function copyLink(){let link=location.origin+location.pathname+'#sell';navigator.clipboard?.writeText(link).then(()=>toast('Referral link copied')).catch(()=>modal('Your referral link',`<p>Select and copy this demo link:</p><input style="width:100%" value="${esc(link)}" readonly>`))}
function invite(){modal('Invite a partner',`<p>Share this workspace link with a partner. This demo link opens the referral page; account invitations require a connected backend.</p><div class="referral"><span>${esc(location.origin+location.pathname+'#sell')}</span>${btn('Copy link',"copyLink()",'copy',true)}</div>`)}
function personalise(category){modal('Make it yours',`<form onsubmit="event.preventDefault();downloadCreative('${category}',this)"><p>Add your details to a monochrome creative.</p><div class="formgrid"><label class="field full">Your name<input name="name" value="Deepak Sharma" required maxlength="40"></label><label class="field full">Phone number<input name="phone" type="tel" placeholder="Your business number" required maxlength="20"></label></div><div class="modalfoot"><button class="primary">${I('download')} Download creative</button></div></form>`)}
function downloadCreative(category,form){let f=new FormData(form),p=posters.find(p=>p[0]===category),words=p[1].split(' '),lines=[],line='';words.forEach(w=>{if((line+' '+w).length>22){lines.push(line);line=w}else line+=(line?' ':'')+w});if(line)lines.push(line);let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1080" height="1080" viewBox="0 0 1080 1080"><rect width="1080" height="1080" fill="#061c48"/><circle cx="1000" cy="300" r="300" fill="none" stroke="#2873bb"/><circle cx="1000" cy="300" r="240" fill="none" stroke="#2873bb"/><text x="80" y="100" font-family="Arial" font-size="27" fill="#aaa">SIGMA0NINE / ${category.toUpperCase()}</text>${lines.map((l,i)=>`<text x="80" y="${320+i*95}" font-family="Arial" font-weight="bold" font-size="70" fill="white">${esc(l)}</text>`).join('')}<text x="80" y="760" font-family="Arial" font-size="28" fill="#bbb">${esc(p[2])}</text><path d="M80 860H1000" stroke="#2873bb"/><text x="80" y="940" font-family="Arial" font-size="34" fill="white">${esc(f.get('name'))}</text><text x="80" y="995" font-family="Arial" font-size="28" fill="#bbb">${esc(f.get('phone'))}</text></svg>`;fileDownload(`incremint-${category}-creative.svg`,svg,'image/svg+xml');closeModal();toast('Personalised creative downloaded')}
function searchPageLinks(value=''){return nav.filter(n=>n[2].toLowerCase().includes(value.toLowerCase())).map(([id,icon,label])=>`<button style="width:100%;justify-content:flex-start;margin-top:6px" onclick="closeModal();go('${id}')">${I(icon)}${label}</button>`).join('')||'<p>No pages match your search.</p>'}
function filterPages(value){document.querySelector('#searchPages').innerHTML=searchPageLinks(value)}
function globalSearch(){modal('Find your next move',`<div class="searchbox">${I('search')}<input autofocus placeholder="Search pages…" aria-label="Search pages" oninput="filterPages(this.value)"></div><div id="searchPages">${searchPageLinks()}</div>`)}
function notifications(){modal('Your updates',`<div class="activity">${I('renew')}<div><strong>3 policy renewals coming up</strong><small>Make a little time for your customers this week.</small></div></div><div class="activity">${I('leads')}<div><strong>${db.leads.filter(l=>l.status==='New').length} new leads in your pipeline</strong><small>A new conversation is a good place to start.</small></div></div>${db.activity.slice(0,5).map(a=>`<div class="activity">${I('check')}<div><strong>${esc(a.text)}</strong><small>${esc(a.date)}</small></div></div>`).join('')}`)}
function settings(){modal('Your workspace',`<div class="person"><div class="avatar">DS</div><div><strong>Deepak Sharma</strong><small>Partner workspace · Demo account</small></div></div><div class="settingsrow"><div><strong>Local workspace data</strong><p>Back up all records as a JSON file.</p></div>${btn('Back up',"fileDownload('incremint-backup.json',JSON.stringify(db,null,2),'application/json')",'download')}</div><div class="settingsrow"><div><strong>Restore backup</strong><p>Import a previously exported workspace.</p></div><input style="max-width:170px" type="file" accept=".json" aria-label="Import backup" onchange="restoreBackup(this.files[0])"></div><p class="subtle">This prototype stores data in your current browser. Live sign-in, multi-user sync, AI and payments are not connected.</p>`)}
async function restoreBackup(file){if(!file)return;try{let data=JSON.parse(await file.text());if(!['bookings','leads','contacts','network','activity'].every(k=>Array.isArray(data[k])))throw Error();if(!data.bookings.every(b=>typeof b.id==='string'&&typeof b.name==='string'&&Number.isFinite(+b.premium)&&b.premium>=0&&typeof b.date==='string'&&typeof b.renewal==='string')||!data.contacts.every(c=>typeof c.name==='string'&&typeof c.id==='string')||!data.leads.every(c=>typeof c.name==='string'&&typeof c.id==='string'))throw Error();modal('Restore this backup?',`<p>This backup contains ${data.bookings.length} bookings, ${data.leads.length} leads and ${data.contacts.length} contacts. Restoring replaces your current browser workspace.</p><div class="modalfoot">${btn('Cancel','closeModal()')}${btn('Replace workspace','confirmRestore()','check',true)}</div>`);window.pendingRestore=data}catch{toast('Please select a valid Sigma0Nine backup')}}
function confirmRestore(){db=window.pendingRestore;save();closeModal();render();toast('Workspace restored')}
window.addEventListener('hashchange',()=>{let next=location.hash.slice(1)||'dashboard';if(next!==current){current=next;filter='All';query='';render()}});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();globalSearch()}});document.addEventListener('keydown',e=>{if(e.key!=='Tab')return;const m=document.querySelector('.modal');if(!m)return;let a=[...m.querySelectorAll('button,input,select,textarea,[tabindex="0"]')].filter(x=>!x.disabled),first=a[0],last=a[a.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault()}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault()}});window.addEventListener('DOMContentLoaded',()=>render());
